def verify():
    assert abs(math.exp(50000 / 8.314 * (1 / 300 - 1 / 310)) - 1.91) < 0.01 and abs(math.log(2) / 0.1 - 6.93) < 0.01
    assert abs(math.log(10) / 0.1 - 23.03) < 0.01 and abs(0.8 / (0.5 * 2 * 0.2) - 4) < 1e-9 and abs(0.9 / 0.01 - 90) < 1e-9
    assert 1 - 1 / 4 == 0.75 and abs(1 - 1 / 3 - 0.6667) < 1e-4 and abs(50 * 2000 / 4180 - 23.92) < 0.01 and 16 / 8 == 2


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
